; stay32.asm -- chapter 38: a cartridge of 32 KB that leaves page 2 alone
; generated by gen38.py
        INCLUDE "msx.inc"
        OUTPUT "stay32.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
a8      EQU VARS                ; port $A8 as INIT finds it
a8now   EQU VARS + 1            ; and after page 2 is switched
myslot  EQU VARS + 2            ; the cartridge's slot ID
sltwas  EQU VARS + 3            ; SLTTBL for its slot at INIT
sltnow  EQU VARS + 4            ; and after the switch
sum     EQU VARS + 6            ; page 2's 16 KB added up, two bytes
regs    EQU VARS + 8            ; pages.asm: the four secondary registers
ids     EQU VARS + 12           ; pages.asm: the slot ID of each page
SSLOT   EQU $FFFF               ; the secondary slot register, in page 3
init:   di
        ld sp, SYS_AREA
        in a, (PPI_A)           ; the slots as INIT finds them
        ld (a8), a
        call here               ; this cartridge's slot ID, for the screen
        ld (myslot), a
        call slt
        ld (sltwas), a
                                ; WHERE IT BREAKS: page 2 left as it is
        in a, (PPI_A)
        ld (a8now), a
        call slt
        ld (sltnow), a
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld d, 3
        ld e, 11
        call at
        ld a, (myslot)
        call hex
        ld e, 15
        call at
        ld a, (myslot)
        call putslot
        ld d, 4
        ld e, 11
        call at
        ld a, (a8)
        call hex
        ld e, 17
        call at
        ld a, (a8now)
        call hex
        ld d, 5
        ld e, 11
        call at
        ld a, (sltwas)
        call hex
        ld e, 17
        call at
        ld a, (sltnow)
        call hex
        VDP_REG 1, $C0          ; the display on, no frame interrupt
        call second             ; the routine in the second half
        call sum2               ; and page 2 added up
        ld (sum), hl
        ld d, 9
        ld e, 11
        call at
        ld hl, (sum)
        call hex16
.end:   jr .end

; here: -> A = the slot ID of page 1, where INIT runs: the primary slot from
; RSLREG and, if EXPTBL says it is expanded, the secondary from SLTTBL, the
; BIOS's copy of the slot's register. Uses A, BC, HL
here:   call RSLREG             ; 18  A = port $A8
        rrca                    ;  5
        rrca                    ;  5
        and 3                   ;  8  page 1's primary slot
        ld c, a                 ;  5
        ld b, 0                 ;  8
        ld hl, EXPTBL           ; 11
        add hl, bc              ; 12
        or (hl)                 ;  8  bit 7 if the slot is expanded
        ret p                   ; 12, or 6  it is not: that is the ID
        ld c, a                 ;  5  1000 00PP
        inc hl                  ;  7
        inc hl                  ;  7
        inc hl                  ;  7
        inc hl                  ;  7  SLTTBL, the same slot
        ld a, (hl)              ;  8
        and %00001100           ;  8  page 1's secondary slot
        or c                    ;  5
        ret                     ; 11

; slt: -> A = SLTTBL for the slot in myslot. Uses A, HL
slt:    ld a, (myslot)
        and 3
        add a, low SLTTBL
        ld l, a
        ld h, high SLTTBL
        ld a, (hl)
        ret

; putslot: A = a slot ID -> "P", or "P-S" for an expanded slot, from the
; address set. Uses A, B
putslot: ld b, a
        and 3
        add a, '0'
        out (VDP_DATA), a       ; the primary slot
        bit 7, b
        ret z
        ld a, '-'
        out (VDP_DATA), a
        ld a, b
        rrca
        rrca
        and 3
        add a, '0'
        out (VDP_DATA), a       ; the secondary
        ret

; sum2: -> HL = page 2's 16 KB, $8000 to $BFFF, added up as bytes, modulo
; 65,536. Uses A, BC, DE, HL
sum2:   ld de, $8000
        ld bc, $4000
        ld hl, 0
.byte:  ld a, (de)
        add a, l
        ld l, a
        jr nc, .next
        inc h
.next:  inc de
        dec bc
        ld a, b
        or c
        jr nz, .byte
        ret

; hex16: HL as four hexadecimal digits, from the address set. Uses A, C
hex16:  ld a, h
        call hex
        ld a, l
        jp hex

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
